import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-10-07","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-10-07","date":"2021-10-07T00:00:00.000Z","updated":"2021-10-09T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可伸缩性","对象存储","块存储","文件系统存储","一致性","去中心化","性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-10-07.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-10-07.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-10-07.md"};function o(n,e,s,h,d,u){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph存储系统性能会议回顾了过去两周的开发进展和讨论，重点在于代码审查、性能优化和未来改进的方向。</p><h4 id="主要议题和讨论内容" tabindex="-1">主要议题和讨论内容 <a class="header-anchor" href="#主要议题和讨论内容" aria-label="Permalink to &quot;主要议题和讨论内容&quot;">​</a></h4><ol><li><p><strong>新PR和更新</strong></p><ul><li>实现了优先级现金的缓存年龄分箱更新。</li><li>讨论了LRU缓存实现中的问题，特别是在roxdb块缓存中的更改可能导致轻微损坏。</li></ul></li><li><p><strong>已关闭的PR</strong></p><ul><li>Prometheus管理器模块PR提供了禁用缓存的能力。</li><li>旧版本的缓存分箱PR被关闭，取而代之的是一个更新和重新基于的版本。</li></ul></li><li><p><strong>更新中的PR</strong></p><ul><li>Neha对管理器TTL缓存实现的审查，以及基于反馈的进一步讨论和更新。</li><li>Igor的PG移除优化PR，之前有测试失败的记录，目前仍在计划中。</li><li>头解码优化讨论，Iliad进行审查，有一些额外的讨论和更新。</li><li>大型PR从日志中移除子树映射，因复杂性需要更多设计文档和讨论。</li></ul></li><li><p><strong>其他讨论</strong></p><ul><li>讨论内存使用问题，可能与创建和销毁大量cgroup时的上游内核bug有关。</li><li>缓存年龄分箱的性能影响讨论，尽管有时会有性能提升，但也可能会有损失。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续审查和测试缓存年龄分箱的实现，特别是解决可能导致SIG故障的问题。</li><li>对于复杂PR如子树映射移除，需要更多的设计文档和讨论，可能分解为更小的部分。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续进行缓存年龄分箱的测试和审查。</li><li>准备设计文档和进一步的讨论，可能分解大PR为更小的可管理部分。</li><li>关注内存使用问题，特别是与cgroup相关的内核bug。</li><li>探讨未来缓存行为的改进和可能的优化方向。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>讨论了关于缓存行为的未来改进和可能的优化方向，包括预分配内存和更静态的内存管理策略。</li><li>探讨了应用程序提供缓存提示的可能性，以优化缓存行为。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议结束后，参与者将在后续会议中继续跟进上述议题。</p>',13)])])}const _=a(r,[["render",o]]);export{c as __pageData,_ as default};
